      'alm-mito': { label: 'الميتوكندريا', desc: 'الميتوكندريا (مفردها ميتوكندريون) أكثر العضيات مشاهدة بالمجهر الضوئي، وقد أظهرت مقاطع الفيديو الملتقطة بالمجهر الضوئي قدرة الميتوكندريا على الحركة والانقسام وتغيير شكلها؛ وهي متخصّصة في القيام بعملية التنفّس الهوائي. <br><small>كتاب الطالب — ص 24</small>' },
      'alm-golgi': { label: 'جهاز جولجي', desc: 'في عام 1898م أدّى استخدام العالم كاميلو جولجي لصبغة خاصة تحتوي على الفضّة إلى اكتشاف جهاز جولجي. ويجمع جهاز جولجي الجُزيئات داخل الخليّة ويعالجها، خصوصًا البروتينات. <br><small>كتاب الطالب — ص 24</small>' },
      'alm-nucleus': { label: 'النواة', desc: 'النواة تركيب كبير نسبيًا تصطبغ بشدّة فتسهل بالتالي رؤيتها بالمجهر. <br><small>كتاب الطالب — ص 24</small>' },
      'alm-chromatin': { label: 'الكروماتين', desc: 'تسمّى المادة التي تصطبغ بشدّة في النواة الكروماتين (كروما تعني اللون). الكروماتين كتلة من الخيوط الملتفّة تتكثف أثناء الانقسام المتساوي على هيئة كروموسومات. <br><small>كتاب الطالب — ص 24</small>' },
      'alm-nucleolus': { label: 'النويّة', desc: 'تركيب صغير واحد أو أكثر يوجد داخل النواة. تشاهد النويّة عادة كجسم شديد الاصطباغ، ووظيفتها استخدام تعليمات DNA الموجود فيها لبناء الرايبوسومات. <br><small>كتاب الطالب — ص 35</small>' },
