    hotspots: {
      "chain": { label: "الجلوكوز على شكل سلسلة مستقيمة", desc: "يمكن كتابة الصيغة الجزيئيّة للسكّريات السداسية بالشكل (C₆H₁₂O₆)، وهذا يعني وجود 6 ذرّات كربون و 12 ذرّة هيدروجين و 6 ذرّات أكسجين في الجُزيء. ويمكن تبيان ترتيب الذرات في جزيء ما من خلال رسم تخطيطي يعرف بالصيغة التركيبية. <br><small>كتاب الطالب — ص 68</small>" },
      "cyclize": { label: "انغلاق السلسلة على نفسها", desc: "يتمثّل أحد المظاهر المهمّة في تركيب السكّريات الخماسيّة والسداسيّة في أن سلسلة الكربون طويلة بما يكفي لأن تنغلق على نفسها لتشكل تركيبًا حلقيًا أكثر ثباتًا. وعندما يشكّل الجلوكوز مثل هذه الحلقة، ترتبط ذرّة الكربون رقم 1 بالأكسجين في ذرّة الكربون رقم 5. <br><small>كتاب الطالب — ص 68</small>" },
      "ring-o": { label: "الأكسجين في الحلقة", desc: "لذلك تحتوي الحلقة على الأكسجين، ولا تكون ذرة الكربون رقم 6 جزءًا من الحلقة. <br><small>كتاب الطالب — ص 68</small>" },
      "c1-oh": { label: "مجموعة الهيدروكسيل على ذرّة الكربون رقم 1", desc: "الشكل ٢-٤ يبيّن أن مجموعة الهيدروكسيل (–OH) على ذرّة الكربون رقم 1 قد توجد أعلى أو أسفل مستوى الحلقة. <br><small>كتاب الطالب — ص 69</small>" },
      "alpha": { label: "ألفا (α)-جلوكوز", desc: "ويسمّى شكل الجلوكوز الذي تكون فيه هذه المجموعة أسفل الحلقة ألفا (α)-جلوكوز، ويسمّى الشكل الذي تكون فيه فوق الحلقة بيتا (β)-جلوكوز. <br><small>كتاب الطالب — ص 69</small>" },
      "beta": { label: "بيتا (β)-جلوكوز", desc: "كما يسمّى الشكلان من المادة الكيميائيّة نفسها الآيزوميرات (المتشكلات) Isomers. وللتنوّع الإضافي الذي يؤمّنه وجود النظيرَين ألفا وبيتا أهميّة كبيرة كما ستشاهد في تراكيب النشا والجلايكوجين والسليلوز. <br><small>كتاب الطالب — ص 69</small>" },
      "simple": { label: "الصيغة الحلقية بشكل بسيط", desc: "في الغالب، وبهدف التبسيط، لا تُكتب ذرات C وH في الصيغ التركيبية الحلقية. <br><small>كتاب الطالب — ص 69</small>" }
    }
